-- SacredSDK / lua / lib / npc.lua  (AUTO-GENERATED — do not hand-edit)
--
-- Every creature / NPC class in Sacred Gold. The `id` is the numeric
-- Type used by the FunkCode `CreateNPC` record (tag 0x01, 'Type=%d').
-- Source: community `sacred_modding - characters.csv` (regenerate with
-- `the generator in sdk/re/py/`).
--
-- NOTE: ids 1..9 here are the CreateNPC Type for the hero models. That
-- is a DIFFERENT namespace from the 8-bit save/item class mask in
-- `classes.lua` (e.g. Vampiress: CreateNPC id 6/7, class bit 32).
--
-- Usage:
--   local NPC = require "npc"
--   NPC.SKELETON                 --> 32
--   NPC.by_id[88].name           --> "D'Cay, Lady of the Orcus"
--   for _,e in ipairs(NPC.ALL) do ... end          -- {id,hex,name,note}
--   NPC.find("Pirate")           --> first entry table named "Pirate"
--   NPC.all_named("Pirate")      --> { ...all Pirate entries... }

local M = { ALL = {}, by_id = {} }

local function add(id, hex, name, note)
  local e = { id = id, hex = hex, name = name, note = note }
  M.ALL[#M.ALL + 1] = e
  M.by_id[id] = e
  return id
end

