-- First entry whose name matches exactly (case-sensitive).
function M.find(name)
  for _, e in ipairs(M.ALL) do if e.name == name then return e end end
end

-- All entries with that exact name (Pirate, Juggler, Cow, ... repeat).
function M.all_named(name)
  local out = {}
  for _, e in ipairs(M.ALL) do
    if e.name == name then out[#out + 1] = e end
  end
  return out
end

-- 474 classes total.
return M
